import React, { useState } from "react";
import { searchMovies, getMovieDetail } from "../api/movieApi";
import { getPosterFromTMDB } from "../api/tmdbApi";
import '../styles.css';

const SearchPage = () => {
  const [query, setQuery] = useState("");
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");

  const handleSearch = async () => {
    if (!query.trim()) return;
    setLoading(true);
    setErrorMsg("");
    setMovies([]);

    try {
      const results = await searchMovies(query);

      // 🚩 디버깅 로그 1: KOFIC에서 받은 초기 검색 결과 확인
      console.log("=============== 1. KOFIC 검색 결과 ===============", results);

      if (results.length === 0) {
        // ...
        return;
      }
      
      const enrichedMovies = await Promise.all(results.map(async (movie) => {
        const detail = await getMovieDetail(movie.movieCd);
        const year = movie.openDt?.substring(0, 4) || "";
        
        // 🚩 디버깅 로그 2: TMDB API로 넘겨주는 정보 확인
        console.log(`------- 2. "${movie.movieNm}" 포스터 요청 시작 -------`);
        console.log({
          title: movie.movieNm,
          year: year,
          nation: movie.repNationNm,
          movieNmEn: movie.movieNmEn
        });

        const posterUrl = await getPosterFromTMDB(movie.movieNm, year, {
            movieNmEn: movie.movieNmEn,
            nation: movie.repNationNm,
        });

        return {
            ...movie,
            ...detail,
            poster_path: posterUrl || "https://via.placeholder.com/120x170?text=No+Image"
        }
      }));
      
      setMovies(enrichedMovies);

    } catch (error) {
      setErrorMsg("영화 검색 중 오류 발생");
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter") handleSearch();
  };

  return (
    <div className="p-4 max-w-4xl mx-auto">
      <h1 className="text-2xl font-bold mb-4">🎬 영화 검색 (KOFIC + TMDB)</h1>

  <div className="flex gap-2 mb-4">
   <input
    type="text"
    placeholder="영화 제목을 입력하세요"
    value={query}
    onChange={(e) => setQuery(e.target.value)}
    onKeyDown={handleKeyDown}
    className="border px-3 py-2 flex-1 rounded"
  />
  <button
    onClick={handleSearch}
    className="bg-blue-500 text-white px-4 py-2 rounded"
  >
    검색
    </button>
  </div>

      {loading && <p>🔍 검색 중...</p>}
      {errorMsg && <p className="text-red-500">{errorMsg}</p>}

      <ul className="space-y-4">
        {movies.map((movie) => (
          <li key={movie.movieCd} className="border p-4 rounded shadow-sm bg-white flex gap-4 items-start">
            <img src={movie.poster_path} alt={movie.movieNm} className="w-32 h-auto rounded flex-shrink-0" />
            <div>
              <h2 className="text-lg font-bold mb-2">
                {movie.movieNm} ({movie.movieNmEn || "N/A"})
              </h2>
              <p><strong>🎬 개봉일:</strong> {movie.openDt || "N/A"}</p>
              <p><strong>🎬 감독:</strong> {movie.directors?.map((d) => d.peopleNm).join(", ") || "N/A"}</p>
              <p><strong>🎭 장르:</strong> {movie.genreAlt || "N/A"}</p>
              <p><strong>🌐 국가:</strong> {movie.repNationNm || "N/A"}</p>
              <p><strong>⏱ 상영시간:</strong> {movie.showTm ? `${movie.showTm}분` : "정보 없음"}</p>
              <p><strong>👨‍🎤 배우:</strong> {movie.actors?.slice(0, 5).map((a) => a.peopleNm).join(", ") || "정보 없음"}</p>
              <p><strong>🔒 관람등급:</strong> {movie.audits?.[0]?.watchGradeNm || "정보 없음"}</p>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default SearchPage;
